#include "testlib.h"
#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

int pickSized(int lo, int hi) {
    int idx = opt<int>("index", 0), cnt = opt<int>("count", 15);
    if (cnt <= 1) return rnd.next(lo, hi);
    if (idx < 0) idx = 0; if (idx >= cnt) idx = cnt - 1;
    ll span = (ll)hi - lo;
    ll a = lo + span * idx / cnt;
    ll b = lo + span * (idx + 1) / cnt;
    if (b < a) b = a;
    if (a > hi) a = hi; if (b > hi) b = hi;
    return rnd.next((int)a, (int)b);
}

vector<pair<int,int>> genGraph(int n, int m) {
    vector<pair<int,int>> e;
    for (int i = 1; i < n; i++) e.push_back({i, i+1});
    int have = n - 1;
    if (m <= have) { e.resize(m); return e; }
    int need = m - have;
    ll max_extra = (ll)n*(n-1)/2 - have;
    if (max_extra <= 0) return e;
    int actual = min((ll)need, max_extra);
    unordered_set<ll> used;
    for (auto &p : e) used.insert((ll)(p.first-1)*n+(p.second-1));
    while ((int)e.size() < have + actual) {
        int a = rnd.next(0, n-2), b = rnd.next(a+1, n-1);
        if (used.insert((ll)a*n+b).second) e.push_back({a+1, b+1});
    }
    return e;
}

int main(int argc, char* argv[]) {
    registerGen(argc, argv, 1);
    opt<int>("seed"); // consume seed
    string typ = opt<string>("type", "random");
    int idx = opt<int>("index", 0);
    int cnt = opt<int>("count", 15);

    const int TMAX = 10000;
    const int NMAX = 200000;
    const int MMAX = 400000;
    const ll SUMN = 200000;
    const ll SUMM = 400000;

    int T = 0;
    vector<int> ns;
    vector<vector<pair<int,int>>> all;

    auto add = [&](int n, int m) {
        int maxm = (int)min((ll)n*(n-1)/2, (ll)MMAX);
        int minm = max(1, n-1);
        m = max(minm, min(maxm, m));
        ns.push_back(n);
        auto e = genGraph(n, m);
        shuffle(e.begin(), e.end());
        all.push_back(e);
    };

    if (typ == "edge_T1") {
        T = 1;
        int n = pickSized(2, min(NMAX, 1000));
        add(n, rnd.next(n-1, min(MMAX, (int)((ll)n*(n-1)/2))));
    } else if (typ == "edge_Tmax") {
        ll ln = SUMN, lm = SUMM;
        while (ln >= 2 && lm >= 1 && T < TMAX) {
            int ni = rnd.next(2, min((int)ln, 20));
            int mi = rnd.next(ni-1, min({(int)lm, MMAX, (int)((ll)ni*(ni-1)/2)}));
            add(ni, mi);
            ln -= ni; lm -= (int)all.back().size();
            T++;
        }
    } else if (typ == "edge_n2_m1") {
        T = 1; add(2, 1);
    } else if (typ == "edge_n2_m3") {
        T = 1; add(2, 1);
    } else if (typ == "edge_n_max") {
        T = 1;
        int n = NMAX;
        add(n, rnd.next(n-1, min({MMAX, (int)((ll)n*(n-1)/2), (int)SUMM})));
    } else if (typ == "edge_m_min") {
        T = 1;
        int n = pickSized(2, min(NMAX, 1000));
        add(n, n-1);
    } else if (typ == "edge_m_max") {
        T = 1;
        int n = pickSized(2, min(NMAX, 1000));
        add(n, (int)min((ll)n*(n-1)/2, (ll)MMAX));
    } else if (typ == "edge_dag_chain" || typ == "edge_hamiltonian_chain") {
        T = 1;
        int n = pickSized(2, min(NMAX, 1000));
        add(n, n-1);
    } else if (typ == "edge_dag_extra" || typ == "edge_hamiltonian_extra") {
        T = 1;
        int n = pickSized(2, min(NMAX, 1000));
        int maxm = (int)min((ll)n*(n-1)/2, (ll)MMAX);
        add(n, rnd.next(n, maxm));
    } else if (typ == "edge_connected_tree") {
        T = 1;
        int n = pickSized(2, min(NMAX, 1000));
        add(n, n-1);
    } else if (typ == "edge_connected_dense") {
        T = 1;
        int n = pickSized(2, min(NMAX, 500));
        int maxm = (int)min((ll)n*(n-1)/2, (ll)MMAX);
        int m = rnd.next(max(max(1,n-1), (int)(maxm*0.7)), maxm);
        add(n, m);
    } else if (typ == "edge_unique_source") {
        T = 1;
        int n = pickSized(2, min(NMAX, 1000));
        add(n, rnd.next(n-1, min(MMAX, (int)((ll)n*(n-1)/2))));
    } else if (typ == "edge_random_dag" || typ == "random") {
        int bucket = min(2, idx * 3 / max(1, cnt));
        if (bucket == 0) {
            ll ln = SUMN, lm = SUMM;
            while (ln >= 2 && lm >= 1 && T < min(100, TMAX)) {
                int ni = rnd.next(2, min((int)ln, 20));
                int mi = rnd.next(ni-1, min({(int)lm, MMAX, (int)((ll)ni*(ni-1)/2)}));
                add(ni, mi);
                ln -= ni; lm -= (int)all.back().size();
                T++;
            }
        } else if (bucket == 2) {
            T = rnd.next(1, 3);
            ll ln = SUMN, lm = SUMM;
            for (int i = 0; i < T && ln >= 2 && lm >= 1; i++) {
                int max_ni = min((int)ln, NMAX);
                int ni = (i+1==T)?max(2,(int)ln):pickSized(max(2,NMAX/10), max_ni);
                int max_mi = min({(int)lm, MMAX, (int)((ll)ni*(ni-1)/2)});
                int mi = rnd.next(ni-1, max_mi);
                add(ni, mi);
                ln -= ni; lm -= (int)all.back().size();
            }
            T = (int)ns.size();
        } else {
            T = pickSized(1, min(50, TMAX/20));
            ll ln = SUMN, lm = SUMM;
            for (int i = 0; i < T && ln >= 2 && lm >= 1; i++) {
                int max_ni = min((int)ln, max(2, (int)(ln / max(1, T-i))));
                int ni = pickSized(2, max_ni);
                int max_mi = min({(int)lm, MMAX, (int)((ll)ni*(ni-1)/2)});
                int mi = rnd.next(ni-1, max_mi);
                add(ni, mi);
                ln -= ni; lm -= (int)all.back().size();
            }
            T = (int)ns.size();
        }
    } else {
        T = 1; add(pickSized(2, 100), 0);
    }
    printf("%d\n", T);
    for (int i = 0; i < T; i++) {
        printf("%d %d\n", ns[i], (int)all[i].size());
        for (auto &p : all[i]) printf("%d %d\n", p.first, p.second);
    }
    return 0;
}

