#include "testlib.h"
#include <bits/stdc++.h>
using namespace std;

int main(int argc, char* argv[]) {
    registerValidation();

    int T = inf.readInt(1, 10000, "T");
    inf.readEoln();

    long long sum_n = 0, sum_m = 0;
    const long long MAX_SUM_N = 200000;
    const long long MAX_SUM_M = 400000;

    for (int t = 0; t < T; t++) {
        int n = inf.readInt(2, 200000, "n");
        inf.readSpace();
        int m = inf.readInt(1, 400000, "m");
        inf.readEoln();

        sum_n += n;
        sum_m += m;
        ensuref(sum_n <= MAX_SUM_N, "sum n = %lld exceeds %lld", sum_n, MAX_SUM_N);
        ensuref(sum_m <= MAX_SUM_M, "sum m = %lld exceeds %lld", sum_m, MAX_SUM_M);

        // 读取边并校验
        vector<pair<int,int>> edges(m);
        set<pair<int,int>> edge_set;
        for (int i = 0; i < m; i++) {
            int u = inf.readInt(1, n, "u");
            inf.readSpace();
            int v = inf.readInt(1, n, "v");
            inf.readEoln();

            ensuref(u != v, "self loop at edge %d: %d %d", i+1, u, v);
            ensuref(edge_set.insert({u, v}).second, "duplicate edge at %d: %d %d", i+1, u, v);
            edges[i] = {u, v};
        }

        // 构建图
        vector<vector<int>> g(n + 1), rg(n + 1);
        vector<int> indeg(n + 1, 0), outdeg(n + 1, 0);
        for (auto &e : edges) {
            int u = e.first, v = e.second;
            g[u].push_back(v);
            rg[v].push_back(u);
            indeg[v]++;
            outdeg[u]++;
        }

        // 1. 检查 DAG（无环）：Kahn 拓扑排序
        vector<int> indeg_copy = indeg;
        queue<int> q;
        for (int i = 1; i <= n; i++) {
            if (indeg_copy[i] == 0) q.push(i);
        }
        int topo_cnt = 0;
        while (!q.empty()) {
            int u = q.front(); q.pop();
            topo_cnt++;
            for (int v : g[u]) {
                if (--indeg_copy[v] == 0) q.push(v);
            }
        }
        ensuref(topo_cnt == n, "graph is not a DAG (has cycle) in test %d", t+1);

        // 2. 检查弱连通性：从任意点出发 BFS（无向图）
        vector<vector<int>> undirected_g(n + 1);
        for (auto &e : edges) {
            int u = e.first, v = e.second;
            undirected_g[u].push_back(v);
            undirected_g[v].push_back(u);
        }
        vector<bool> vis(n + 1, false);
        queue<int> bfs_q;
        bfs_q.push(1);
        vis[1] = true;
        int comp_cnt = 0;
        while (!bfs_q.empty()) {
            int u = bfs_q.front(); bfs_q.pop();
            comp_cnt++;
            for (int v : undirected_g[u]) {
                if (!vis[v]) {
                    vis[v] = true;
                    bfs_q.push(v);
                }
            }
        }
        ensuref(comp_cnt == n, "graph is not connected (weakly) in test %d", t+1);

        // 3. 检查 m >= n-1（连通图至少 n-1 条边）
        ensuref(m >= n - 1, "m=%d < n-1=%d for a connected graph in test %d", m, n-1, t+1);
    }

    inf.readEof();
    return 0;
}
